#nullable enable
using System;
using System.Collections.Generic;

namespace KitveiHakodesh.Core.LocalFiles.ToratEmet;

/// <summary>
/// The Torat Emet program names its folders and book files in English transliteration
/// (001_TORA, a01_Genesis.txt) and shows Hebrew names instead. This is that translation, for every host and page:
/// file search (index terms + result titles) and UserSpace (tree names and ordering).
///
/// Source of the table (ToratEmetNamesData, generated by generate-torat-emet-names.py from an install): the program's own
/// Config.txt [TranslateDictionary] (English folder token = Hebrew name) and BooksConfig.txt (the title of each book file).
/// Lookup is by the path UNDER the install's "Books" folder, so it works wherever the install is; the user's own books
/// (ToratEmetUserData\MyBooks) are never translated.
/// </summary>
public static class ToratEmetNames
{
    /// <summary>"Torat Emet" in Hebrew: added as a search term to every file whose path holds the folder word ToratEmet.</summary>
    public const string SearchPhrase = "תורת אמת";

    private const string FolderWord = "ToratEmet";

    internal sealed class Tables
    {
        public readonly Dictionary<string, string> FolderTitles = new(StringComparer.OrdinalIgnoreCase);
        public readonly Dictionary<string, (string Title, string Forced)> BookTitles = new(StringComparer.OrdinalIgnoreCase);
    }

    private static readonly Lazy<Tables> Data = new(() => Parse(ToratEmetNamesData.Rows));

    internal static Tables Parse(string rows)
    {
        var tables = new Tables();
        foreach (var raw in rows.Split('\n'))
        {
            var row = raw.TrimEnd('\r');
            if (row.Length < 4) continue;
            var cells = row.Split('\t');
            if (cells.Length < 3) continue;
            if (cells[0] == "F") tables.FolderTitles[cells[1]] = cells[2];
            else if (cells[0] == "B") tables.BookTitles[cells[1]] = (cells[2], cells.Length > 3 ? cells[3] : "");
        }
        return tables;
    }

    /// <summary>True when the full path holds the folder word ToratEmet at any level (any case).</summary>
    public static bool IsToratEmetPath(string? fullPath) =>
        !string.IsNullOrEmpty(fullPath) && fullPath!.IndexOf(FolderWord, StringComparison.OrdinalIgnoreCase) >= 0;

    /// <summary>
    /// The path segments under the install's Books folder, or null when the path is not under one. "Under an install's Books":
    /// a folder named exactly Books that lies below a folder whose name holds ToratEmet but not UserData.
    /// </summary>
    internal static string[]? SegmentsUnderInstallBooks(string? fullPath)
    {
        if (!IsToratEmetPath(fullPath)) return null;
        var segments = fullPath!.Replace('/', '\\').Split(new[] { '\\' }, StringSplitOptions.RemoveEmptyEntries);
        int install = -1;
        for (int i = 0; i < segments.Length && install < 0; i++)
            if (segments[i].IndexOf(FolderWord, StringComparison.OrdinalIgnoreCase) >= 0
                && segments[i].IndexOf("UserData", StringComparison.OrdinalIgnoreCase) < 0) install = i;
        if (install < 0) return null;
        for (int i = install + 1; i < segments.Length; i++)
            if (string.Equals(segments[i], "Books", StringComparison.OrdinalIgnoreCase))
            {
                var rest = new string[segments.Length - i - 1];
                Array.Copy(segments, i + 1, rest, 0, rest.Length);
                return rest;
            }
        return null;
    }

    /// <summary>The folder's token: its name without the leading sort number ("01_BERESHIT" -> "BERESHIT").</summary>
    private static string FolderToken(string name)
    {
        int i = 0;
        while (i < name.Length && name[i] >= '0' && name[i] <= '9') i++;
        return i > 0 && i < name.Length && name[i] == '_' ? name.Substring(i + 1) : name;
    }

    /// <summary>Hebrew name of a folder under an install's Books folder; null for the Books folder itself, any other path, or an unknown folder.</summary>
    public static string? FolderTitle(string? fullPath)
    {
        var rest = SegmentsUnderInstallBooks(fullPath);
        if (rest == null || rest.Length == 0) return null;
        return Data.Value.FolderTitles.TryGetValue(FolderToken(rest[rest.Length - 1]), out var title) ? title : null;
    }

    /// <summary>Hebrew name of a book file under an install's Books folder (no extension); null when there is none.</summary>
    public static string? FileTitle(string? fullPath)
    {
        var rest = SegmentsUnderInstallBooks(fullPath);
        if (rest == null || rest.Length == 0) return null;
        return Data.Value.BookTitles.TryGetValue(string.Join("\\", rest), out var book) ? book.Title : null;
    }

    /// <summary>The name to show for a folder or a file: the Hebrew name when there is one, else null.</summary>
    public static string? Title(string? fullPath, bool isFolder) => isFolder ? FolderTitle(fullPath) : FileTitle(fullPath);

    /// <summary>
    /// Extra search terms of a file's path (lower-cased, as the index matches): the Hebrew phrase for any path with ToratEmet in it;
    /// under an install's Books also the Hebrew name of every folder on the way and of the book (its title and ForcedBookName).
    /// Quote forms are added both ways (the program writes a double quote as two single quotes).
    /// </summary>
    public static IReadOnlyList<string> SearchTerms(string? fullPath)
    {
        var terms = new List<string>();
        if (!IsToratEmetPath(fullPath)) return terms;
        terms.Add(SearchPhrase);
        var rest = SegmentsUnderInstallBooks(fullPath);
        if (rest == null) return terms;
        var seen = new HashSet<string>(StringComparer.Ordinal) { SearchPhrase };
        void Add(string? name)
        {
            if (string.IsNullOrWhiteSpace(name)) return;
            var lower = name!.Trim().ToLowerInvariant();
            if (seen.Add(lower)) terms.Add(lower);
            var quoted = lower.Replace("''", "\"");
            if (quoted != lower && seen.Add(quoted)) terms.Add(quoted);
        }
        for (int i = 0; i < rest.Length - 1; i++)
            if (Data.Value.FolderTitles.TryGetValue(FolderToken(rest[i]), out var folder)) Add(folder);
        if (rest.Length > 0)
        {
            if (Data.Value.BookTitles.TryGetValue(string.Join("\\", rest), out var book)) { Add(book.Title); Add(book.Forced); }
            else if (Data.Value.FolderTitles.TryGetValue(FolderToken(rest[rest.Length - 1]), out var own)) Add(own);
        }
        return terms;
    }
}
